  ('0592f629-cc75-5e56-85c5-0641a93376b2', null, (select id from public.skills where slug = 'write-g8-narrative-writing'), null, 'medium',
   $q$What does the dialogue in sentences 14 and 15 mainly reveal?$q$, $q$[{"text":"The narrator was the one who identified the bird.","is_correct":false,"misconception_token":"wrong-speaker"},{"text":"The bird count is finished for the whole day.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Grandpa is annoyed that the narrator interrupted him.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"The sighting is rare and exciting even for Grandpa.","is_correct":true}]$q$::jsonb, $q$The sighting is rare and exciting even for Grandpa.$q$, $q$Grandpa whispers and says he has seen this bird only twice in twenty-two years, which shows how rare and special the moment is. Grandpa, not the narrator, names the bird.$q$, 'draft', '4bde5af7-c78b-5cd5-874a-1185363bc282')
