  ('3a893fae-5a69-5605-925b-1de5b387a90c', null, (select id from public.skills where slug = 'write-g8-narrative-writing'), null, 'medium',
   $q$Sentence 13 rushes past an important moment. Which revision best slows the pacing with description?$q$, $q$[{"text":"He played the rest of the piece as quickly as he possibly could.","is_correct":false,"misconception_token":"speeds-up-pacing"},{"text":"He played the rest of the piece, which was written over a century ago.","is_correct":false,"misconception_token":"off-focus-detail"},{"text":"He played the rest of the piece, and then he was done playing.","is_correct":false,"misconception_token":"summary-no-detail"},{"text":"His bow glided through the slow middle section, and the final high note rang clear across the dark room.","is_correct":true}]$q$::jsonb, $q$His bow glided through the slow middle section, and the final high note rang clear across the dark room.$q$, $q$The correct choice describes the music as it happens, so the reader stays inside the performance. Adding the age of the piece gives a fact that does not slow down or deepen this moment.$q$, 'draft', '07a8501f-fef4-5e95-8e0d-e51beaec2332')
