  ('50b6a83a-fbf7-5b95-b511-edad686c53d9', null, (select id from public.skills where slug = 'write-g8-narrative-writing'), null, 'easy',
   $q$Which sentence should be removed because it interrupts the most exciting moment of the story?$q$, $q$[{"text":"sentence 11","is_correct":false,"misconception_token":"removes-motivation"},{"text":"sentence 2","is_correct":false,"misconception_token":"removes-situation"},{"text":"sentence 13","is_correct":false,"misconception_token":"removes-key-description"},{"text":"sentence 15","is_correct":true}]$q$::jsonb, $q$sentence 15$q$, $q$Sentence 15 is a science fact dropped between the narrator's amazement and the dad's reaction, so it breaks the moment. Sentence 13 must stay because it shows what the comet looks like.$q$, 'draft', 'a16a8458-1b5f-5b95-a034-e4a19bbd7b00')
