values
  ('1db99aa1-55c7-5617-93b2-92cd59d25914', null, (select id from public.skills where slug = 'write-g8-narrative-writing'), null, 'medium',
   $q$Sentences 9 through 11 summarize a conversation. Which revision uses dialogue to build suspense?$q$, $q$[{"text":"\"Comets are the most amazing thing in the sky,\" my dad said happily.","is_correct":false,"misconception_token":"dialogue-contradicts-scene"},{"text":"\"Okay,\" said my dad. \"Okay,\" I said back to him.","is_correct":false,"misconception_token":"dialogue-reveals-nothing"},{"text":"My dad yawned. \"It's almost midnight. Maybe the comet stayed home tonight.\" \"Five more minutes,\" I begged.","is_correct":true},{"text":"My dad yawned and said it was late, and I said that I wanted to stay longer.","is_correct":false,"misconception_token":"summary-not-dialogue"}]$q$::jsonb, $q$My dad yawned. "It's almost midnight. Maybe the comet stayed home tonight." "Five more minutes," I begged.$q$, $q$The correct choice lets both characters speak and shows the dad ready to quit while the narrator pleads, which raises suspense. The first choice reports the same talk without any actual dialogue.$q$, 'draft', 'a16a8458-1b5f-5b95-a034-e4a19bbd7b00')
