  ('cca97443-c7c4-5e61-9b33-ff6b966f44bf', null, (select id from public.skills where slug = 'write-g8-narrative-writing'), null, 'medium',
   $q$In sentence 13, how does the comparison "like a thumbprint on a window" help the narrative?$q$, $q$[{"text":"It shows that the narrator felt disappointed by the comet.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"It helps the reader picture how faint and blurry the comet looked.","is_correct":true},{"text":"It shows that the telescope lens was dirty and needed cleaning.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It suggests that the comet was very close to the field.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It helps the reader picture how faint and blurry the comet looked.$q$, $q$A thumbprint on glass is a soft, hazy smudge, so the simile shows how the comet appeared. Reading it as a real thumbprint on the lens takes the comparison literally.$q$, 'draft', 'a16a8458-1b5f-5b95-a034-e4a19bbd7b00')
